package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class TorrentMultipartTest {
 @Test public void exactBytesMatchLegacyEncoderIncludingUnicodeAndBinary()throws Exception{Map<String,String> fields=new LinkedHashMap<>();fields.put("api","fixture-api");fields.put("destination","Filmek/Árvíztűrő");byte[] file={0,13,10,(byte)255,7};String boundary="FixedBoundary",field="torrent",filename="árvíz.torrent";ByteArrayOutputStream old=new ByteArrayOutputStream();for(Map.Entry<String,String> value:fields.entrySet())old.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\""+value.getKey()+"\"\r\n\r\n"+value.getValue()+"\r\n").getBytes(StandardCharsets.UTF_8));old.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\""+field+"\"; filename=\""+filename+"\"\r\nContent-Type: application/x-bittorrent\r\n\r\n").getBytes(StandardCharsets.UTF_8));old.write(file);old.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));assertArrayEquals(old.toByteArray(),TorrentMultipart.encode(boundary,fields,field,filename,file));assertArrayEquals(new byte[]{0,13,10,(byte)255,7},file);}
 @Test public void draftBytesAreClearedAfterCloseAndNewDraft(){TorrentDraft draft=new TorrentDraft();draft.reset();draft.bytes=new byte[32];draft.close();assertNull(draft.bytes);draft.reset();assertNull(draft.bytes);}
}
